INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (34, 263, 'BOPET CAPACITOR FILM', '../upload/image/20180826/20180826204735_35949.jpg', '<p></p><p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style=''font-family:"font-size:22px;''><b><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPET CAPACITOR FILM</span><br/> <br/> </span></b><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">It is used for film-capacitor (and other electrical insulation material.) which features dielectric strength, dielectric constant and volume resistance, low dielectric loss, good mechanical performance and dimension stability.</span></span></span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Thickness :3-12 UM</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Width : 500,620,670 MM</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Net weight per roll about : 50KGS/roll</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Inner plastic tube core : 3”,6” (76MM ,152MM )</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">By the way , we also manufacture the BOPET metalized (VM/--Zn /Al ) capacitor film.</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Technological data for customer’s reference ,</span></p> <p style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"></p> <table border="1" cellpadding="0" cellspacing="0" style="text-align:left;color:#59595B;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <tbody> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;" valign="top" width="158"> <p style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Density</span></p> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;" valign="top" width="76"> <p style="text-indent:20pt;"> <span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">g/cm</span><sup><span style="color:#E53333;font-family:Tahoma;font-size:18px;">3</span></sup></span></p> </td> <td colspan="3" style="text-align:left;font-family:宋体;font-size:9pt;" valign="top" width="334"> <p style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">1.400+/-0.005</span></p> </td> </tr> <tr> <td style="text-align:left;font-family:宋体;font-size:9pt;" valign="top" width="158"> <p style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">melting point</span></p> </td> <td style="text-align:left;font-family:宋体;font-size:9pt;" valign="top" width="76"> <p style="text-indent:20pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">℃</span></p> </td> <td colspan="3" style="text-align:left;font-family:宋体;font-size:9pt;" valign="top" width