INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (34, 258, '4.5 Microns BOPET Film silver metallized', '../upload/image/20180826/20180826204832_60070.jpg', '<p></p><h3 style=''text-align:left;color:red;text-indent:0px;font-family:"font-style:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;">4.5 Microns BOPET Film silver metallized</span></span> </h3> <h3 style=''text-align:left;color:red;text-indent:0px;font-family:"font-style:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;"> 4.5 Microns BOPET Film silver metallized, Bopet polyester metallized film has a super reflective, mirror- like surface. It is a oriented polyester film with a very</span></span> </h3> <h3 style=''text-align:left;color:red;text-indent:0px;font-family:"font-style:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;">thin coating of aluminum that is vacuum deposited on to the surface of the film. This film is used in a variety of</span></span> </h3> <h3 style=''text-align:left;color:red;text-indent:0px;font-family:"font-style:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;">industrial and applications, including printing, packaging, crafts and many other applications. </span></span> </h3> <h3 style=''text-align:left;color:red;text-indent:0px;font-family:"font-style:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;">Main features of bopet polyester metallized film</span></span> </h3> <h3 style=''text-align:left;color:red;text-indent:0px;font-family:"font-style:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;">a. Good Metal Bond Strength</span></span> </h3> <h3 style=''text-align:left;color:red;text-indent:0px;font-family:"font-style:normal;background-color:#FFFFFF;''> <span