INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (34, 188, 'BOPET film (Polyester film) 12,23,36 Microns', '../upload/image/20180923/20180923113150_21156.jpg', '<p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>BOPET film (Polyester film)</strong></span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPET film (biaxially oriented Polyester films) featurines good thermal stability and tenacity; low air and water permeability; applicable to vacuum aluminum plating, compound package, cooking bag manufacture, etc. </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Featuring : Having the good adhesion with ink and coating, can be used for multi-color printings with good flatness. Is mainly used in heat-sealing bags of frozen food, industrial products and cosmetics packaging. </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> BOPET film including BOPP packing film, BOPET lamination film, BOPET insulation film, BOPET sheets, BOPET capacitor film, BOPET thermal transfer film,metallized BOPET film and so on.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Specification:</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">thickness: 2.5-10 microns,12 microns-36 microns, 75 microns-150 microns ,185 microns-380 microns, 500 microns </span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">width :90-2400MM </span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">length : </span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">6000,9000,12000,24000,36000,55000,65000m </span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Polyester film is wound around paper shaft with an internal diameter of 76.2mm-152.4mm and covered with polyethylene film; each coil is supported by damper and put in carton; medium and large package needs wooden mount.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Customer''s own requirement is available for us such as printed OEM logos and private label or particular size and package style.</span></p> <p style="text-indent:72.3pt;"> <b><span style="color:#E53333;font-family:Tahoma;font-size:18px;font-weight:bold;">Polyester film test report </span></b></p> <div align="center"> <table border="1" cellspacing="0" style="border:currentColor;width:522.25pt;border-collapse:collapse;"> <tbody> <tr> <td colspan="2" style="border:1pt solid windowtext;background-color:transparent;" valign="center" width="134"> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Film item</span></p> </td> <td colspan="2" style="background-color:transparent;" valign="center" width="104"> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPET</span></p> </td> <td style="background-color:transparent;" valign="center" width="81"> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Date </span></p> </td> <td style="background-color:transparent;" valign="center" width="103"> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">201</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">8</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">.2</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">.17 </span></p> <p style="text-indent:6pt;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">17:52</span></p> </td> <td style="background-color:transparent;" valign="center" width="131"> <p align="center" style="text-align:center;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Quantity </span></p> </td> <td colspan="2" style="background-color:transparent;" valign="center" width="141"> <p align="center" style=