INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (34, 130, '4.5Microns BOPET Film for printing &amp; laminating', '../upload/image/20180922/20180922162823_41635.jpg', '<p><span style=''color:#FF0000;line-height:36px;font-family:Calibri, "font-size:24px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <p></p><p><strong><span style="font-family:Verdana;font-size:18px;color:#009900;"><strong><strong><strong><span style="font-size:18px;">4.5Microns </span></strong></strong><span style="font-size:18px;">B-Grade BOPET Film: Cost-Effective TTR &amp; Lamination Base</span></strong></span></strong></p> <p class="MsoNormal" font-size:24px="" style="text-wrap-mode: wrap; color: rgb(255, 0, 0);"><strong><span style="font-family:Verdana;font-size:18px;color:#009900;"><strong><span style="font-size:18px;">4.5Microns BOPET Film for printing &amp; laminating</span><br/> </strong></span></strong></p> <p class="MsoNormal" font-size:24px="" style="text-wrap-mode: wrap; color: rgb(255, 0, 0);"><strong><br/> </strong></p> <p class="MsoNormal" font-size:24px="" style="text-wrap-mode: wrap; color: rgb(255, 0, 0);"><strong><span style="font-family:Verdana;font-size:18px;color:#009900;"><strong>4.5M<span style="font-size:18px;">ic B</span></strong></span><strong><span style="color:#009900;font-size:18px;font-family:Verdana;">-Grade BOPET films, which are a strategic choice for cost-sensitive applications where the extreme precision of A-grade material isn''t strictly necessary, the 4.5 Micron B-Grade BOPET for printing and lamination, specifically tailored for the TTR market.</span></strong></strong></p> <p><br/></p> <p class="MsoNormal" font-size:24px="" style="text-wrap-mode: wrap; color: rgb(255, 0, 0);"><span style="font-family:Verdana;font-size:18px;color:#009900;"><strong>While maintaining the core physical properties of polyester, our B-Grade series is optimized for high-volume production in the Barcode and Fax ribbon industries. This grade offers a balance between industrial-grade performance and economic efficiency.</strong></span></p> <p class="MsoNormal" font-size:24px="" style="text-wrap-mode: wrap; color: rgb(255, 0, 0);"><span style="font-family:Verdana;font-size:18px;color:#009900;"><strong>Quality Profile: B-Grade vs. Standard</strong></span></p> <p class="MsoNormal" font-size:24px="" style="text-wrap-mode: wrap; color: rgb(255, 0, 0);"><span style="font-family:Verdana;font-size:18px;color:#009900;"><strong>B-Grade film typically features the same thermal resistance as A-grade but may have minor variations that do not impact the final transfer quality in standard applications:</strong></span></p> <ul font-size:24px="" style="text-wrap-mode: wrap; color: rgb(255, 0, 0);"> <li class="MsoNormal"> <span style="font-family:Verdana;font-size:18px;color:#009900;"><strong>Surface Consistency:</strong></span><span style="font-family:Verdana;font-size:18px;color:#009900;"><strong> Minor surface visual variations that do not affect ink adhesion or back-coating.</strong></span>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (34, 504, '4.0-4.5 Microns vacuum aluminum metallized polyester BOPET film silver', '../upload/image/20260223/20260223173016_39451.jpg', '<p>4.0-4.5 Microns vacuum aluminum metallized polyester BOPET film silver&nbsp;<br/> 4.0-4.5Microns vacuum aluminum metallized polyester BOPET film silver for printing &amp; lamination.&nbsp;<br/> Thickness of BOPET polyester basic film: 4.0,4.2,4.3,4.4,4.5,4.55,4.6,4.8,5.0,5.7,6.0um&nbsp;<br/> thcikenss of the vacuum aluminum metallized layer : 0.005-0.01microns<br/> width of BOPET polyester basic film: 910,902,935,980,1010,1020,1030,1050,1110,1260,1300,1480mm<br/> length of 4.5Microns vacuum aluminum metallized polyester:15000,18500,20000,24000,36000m&nbsp;<br/> feature of 4.5Microns vacuum aluminum metallized polyester: silver metallized<br/> 4.0-4.5Microns vacuum aluminum metallized polyester BOPET film silver, unprinting &amp;&nbsp; uncoating ( for priting and laminating) ,<br/> have stability features in metallized application and thickness stability,in good heat resistance,easy processing in laminating<br/> Our company (Asia pacific industry group) offer ?4.0-4.5Microns vacuum aluminum metallized polyester BOPET film products to the world market sufficiently.&nbsp;<br/> <p>H.S CODE of 4.0-4.5Microns polyester BOPET vacuum aluminum metallized film: 3920620000</p> <p><img src="../upload/image/no-photo.png" alt="" /></p> <p><img src="../upload/image/no-photo.png" alt="" /></p>', '2026-09-06 20:58:46');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (34, 359, '4.5Mic BOPET film clear transparent , unprinting & with one side coated the other side uncoating (for priting and laminating)', '../upload/image/20211216/20211216093057_74000.jpg', '<p></p> <p><span style="color:#009900;font-family:Tahoma;"><span style="font-family:Tahoma;font-size:18px;color:#009900;">4.5Mic BOPET TTR film With </span><span style="color:#009900;font-family:Tahoma;font-size:18px;">One Side Coated </span><br/> </span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">4.5Mic BOPET film Clear transparent, Unprinting. With one side coated for TTR usage (Thernal transfer ribbons) , the other side uncoating,</span></p> <p><span style="font-family:Tahoma;font-size:18px;color:#009900;">Besides </span><span style="color:#009900;font-family:Tahoma;"><span style="font-family:Tahoma;font-size:18px;color:#009900;">4.5Mic BOPET film clear transparent , with two sides</span><span style="color:#009900;font-family:Tahoma;font-size:18px;"> unprinting &amp; </span><span style="font-family:Tahoma;font-size:18px;color:#009900;"> uncoating (for printing and laminating),&nbsp; </span></span><span style="font-family:Tahoma;font-size:18px;color:#009900;">and there are one side coated 4.5Mic BOPET TTR film.</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">this is : </span><span style="color:#009900;font-family:Tahoma;font-size:18px;">4.5Mic BOPET film Clear transparent, Unprinting and one side coated for TTR usage (Thernal transfer ribbons) , the other side uncoating,</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> and you can use print and laminating at the uncoating side), the coated side was very smooth , and it was suit for the label machine to print the labels and the printing speed can</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;"> be fast, if without the smooth side. The label machine will be can not make sure the fast speed during printing.) </span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Thickness: 4.5Microns (4.4Microns film +0.1microns coating layer)</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:18px;">Width: 1010MM mainly, 680MM mainly, 650MM</span><span style="color:#009900;font-family:Tahoma;font-size:18px;">,900MM,1400MM...</span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Length:12000-32000M (18500M mainly)</span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Inner paper tube core: 6 inches /</span><span style="color:#009900;font-family:Tahoma;font-size:18px;">152MM</span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Packing: Standard packing ( bubble film +kraft paper +plastic insert) </span></p> <p><span style="color:#009900;font-family:Tahoma;font-size:18px;">Quantity : 150tons /month</span></p> <p><br/></p>', '2026-09-06 20:58:45');